export function TodoList({ todos, onToggle, onDelete }: Props) {
  const [filter, setFilter] = useState<Filter>("all");
  const visible = useMemo(() => todos.filter(t => filter === "all" || (filter === "done") === t.done), [todos, filter]);
  if (!todos.length) return <p className="empty">Nothing to do! Add a task above to get started with your day.</p>;
  return (
    <section className="todo-list" aria-label="Todos">
      <header>
        <h2>Todos ({visible.length})</h2>
        <FilterBar value={filter} onChange={setFilter} options={["all", "active", "done"]} />
      </header>
      <ul>
        {visible.map(todo => (
          <li key={todo.id} className={todo.done ? "done" : undefined} onClick={() => onToggle(todo.id)}>
            <input type="checkbox" checked={todo.done} readOnly /> {todo.title}
            {todo.due && <time dateTime={todo.due.toISOString()}>{formatDate(todo.due)}</time>}
            <button onClick={e => { e.stopPropagation(); onDelete(todo.id); }}>×</button>
          </li>
        ))}
      </ul>
      {visible.length === 0 ? <p>No matching todos.</p> : visible.length > 10 ? <Pagination total={visible.length} /> : null}
      <footer>
        Showing <strong>{visible.length}</strong> of <strong>{todos.length}</strong> items. <a href="/help">Need help?</a>
      </footer>
    </section>
  );
}

