  return (
    <section className="todo-list" aria-label="Todos">
      <header>
        <h2>Todos ({visible.length})</h2>
        <FilterBar
          value={filter}
          onChange={setFilter}
          options={["all", "active", "done"]}
        />
      </header>
      <ul>
        {visible.map((todo) => (
          <li
            key={todo.id}
            className={todo.done ? "done" : undefined}
            onClick={() => onToggle(todo.id)}
